INSERT INTO doan.tour (id, name, address, start_time, end_time, rating, total_rating, review_count, description, attraction_id) VALUES
(1, 'Buổi biểu diễn múa rối nước Thăng Long', 'Thang Long Water Puppet Theatre, Đinh Tiên Hoàng, Ly Thai To, Hoàn Kiếm, Hanoi', '08:00:00', '12:00:00', 4, 10, 10, 'Trải nghiệm này sẽ mang đến cho bạn cơ hội khám phá nghệ thuật múa rối nước xa xưa ở Hà Nội. Bạn sẽ ghé thăm nhà hát múa rối nước Thăng Long mang tính biểu tượng, nơi bạn có thể xem những nghệ sĩ múa rối điêu luyện trình diễn. Vé bao gồm buổi biểu diễn múa rối kéo dài 50 phút sử dụng các nhạc cụ truyền thống và những câu truyện dân gian Việt Nam.', 29),
(2, 'Tour ẩm thực đường phố có hướng dẫn', 'Hà Nội', '10:00:00', '16:00:00', 4, 10, 10, 'Chuyến tham quan đi bộ riêng này sẽ đưa bạn đi khám phá một số món ăn đường phố biểu tượng nhất của Hà Nội cùng với một hướng dẫn viên địa phương. Sau khi gặp mặt tại chỗ nghỉ của bạn trong Khu phố cổ, bạn sẽ đến thăm Hồ Hoàn Kiếm, được mệnh danh là trái tim thủ đô Hà Nội. Từ đây, bạn sẽ len lỏi qua những con phố nhộn nhịp và đặt chân đến một vài quán ăn đường phố nổi tiếng. Bạn sẽ được nếm thử các món ăn như bún chả và bánh cuốn để khám phá thực đơn. Trước khi kết thúc chuyến tham quan, mời bạn dừng chân thưởng thức món tráng miệng và cà phê trứng.', 29),
(3, 'Du thuyền đêm trên sông Hàn', '26 Bach Dang, Thach Thang, Da Nang', '06:00:00', '18:00:00', 4, 10, 10, 'Với tour du lịch này, bạn sẽ được khám phá các thắng cảnh ở Đà Nẵng về đêm trong lúc du thuyền dọc sông Hàn. Sau khi đến bến cảng, bạn sẽ lên thuyền để bắt đầu hành trình xuôi theo con sông. Xuyên suốt chuyến đi, bạn sẽ được ngắm nhìn quang cảnh thành phố và một số địa danh, bao gồm Cầu Tình yêu và Vòng quay Sun Wheel. Bạn cũng sẽ có cơ hội thưởng thức nhạc sống, biểu diễn ngay trên boong tàu.', 29),
(4, 'Tour Bà Nà Hills trọn ngày với bữa trưa buffet', '43 Võ Văn Kiệt, An Hải, Đà Nẵng', '09:00:00', '15:00:00', 4, 10, 10, 'Trong chuyến tham quan trong ngày này, bạn sẽ khám phá những nét nổi bật về văn hóa và lịch sử của Bà Nà Hills. Sau khi bạn được đón tại khách sạn hoặc gặp hướng dẫn viên, bạn sẽ di chuyển đến ga cáp treo Bà Nà. Trên tuyến cáp treo hiện đại, trước tiên bạn sẽ đến thăm Cầu Vàng, chiếc cầu nổi tiếng với hai bàn tay khổng lồ được điêu khắc tinh xảo. Sau đó, bạn sẽ tiếp tục đi cáp treo để khám phá 9 khu vườn của Le Jardin D_Amour và Chùa Linh Ứng. Từ đây, bạn sẽ đến thăm Làng Pháp, Thiền viện, Nhà Bia và Trà quán.', 29),
(5, 'Tour tham quan địa đạo Củ Chi theo nhóm nhỏ', 'KIM TRAVEL, Thủ Khoa Huân 17, Thành phố Hồ Chí Minh', '13:00:00', '20:00:00', 4, 10, 10, 'Trong chuyến tham quan theo nhóm nhỏ vào buổi sáng hoặc buổi chiều này, bạn sẽ được khám phá mạng lưới đường hầm dưới lòng đất tại địa đạo Củ Chi và tìm hiểu về lịch sử lâu đời và tầm quan trọng của nó với thành phố. Bạn sẽ xem một bộ phim 3D về cuộc hành quân trên bộ lớn nhất của Mỹ trong Chiến tranh Việt Nam. Trong các đường hầm dưới lòng đất, bạn sẽ được hiểu rõ hơn về cách thức hoạt động của khu phức hợp và cuộc sống trong các đường hầm từ năm 1961 đến năm 1972 đã diễn ra như thế nào. Bạn sẽ có cơ hội đi thử một lối vào nhỏ ẩn trong đường hầm để hiểu cách mọi người từng di chuyển trong đó. Trong các đường hầm sẽ có các kho chứa, cửa bẫy, nhà máy sản xuất vũ khí, trung tâm chỉ huy và bệnh viện dã chiến.', 29);
